def deep_merge(base, override):
    """Layer `override` over `base`."""
    # Start with a deep copy of base
    result = _deep_copy(base)

    # Apply overrides
    for key, value in override.items():
        if value is None:
            # Remove key if override value is None
            result.pop(key, None)
        elif key in result and isinstance(result[key], dict) and isinstance(value, dict):
            # Recursively merge dicts
            result[key] = deep_merge(result[key], value)
        else:
            # Replace with deep copy of the override value
            result[key] = _deep_copy(value)

    return result


def _deep_copy(obj):
    """Deep copy an object (handles dicts, lists, and scalars)."""
    if isinstance(obj, dict):
        return {key: _deep_copy(value) for key, value in obj.items()}
    elif isinstance(obj, list):
        return [_deep_copy(item) for item in obj]
    else:
        return obj
